get_ipython().run_cell_magic('writefile', f'{STAGING}/e8_analysis.py', '"""E8 CPU extension of the completed historical fp32 crossed tag/text experiment."""\nimport argparse\nimport hashlib\nimport importlib.metadata\nimport itertools\nimport json\nimport time\nfrom pathlib import Path\nimport numpy as np\nimport pandas as pd\nfrom scipy.stats import spearmanr\n\nSTUDIES = {\'it2\': \'holdout\', \'nllb\': \'confirm\'}\nARCHITECTURE = {\'it2\': \'requested target tag changes encoder input; all encoder representations may change\',\n                \'nllb\': \'requested target tag changes decoder prefix; no source-position target-tag attention\'}\nCOMPONENTS = {\'it2\': [\'source_tag\', \'target_tag\', \'eos\', \'unknown\', \'punctuation\', \'lexical\'],\n              \'nllb\': [\'source_code\', \'eos\', \'punctuation\', \'lexical\']}\nSAMPLE_HASH = \'64847ea1866cf6e728315df46e3743f8f69f94614cfde895f53f748ff9d7953c\'\n\n\ndef require(value, message):\n    if not bool(value):raise ValueError(message)\n\n\ndef progress(message):\n    print(time.strftime(\'%H:%M:%S\'), message, flush=True)\n\n\ndef sha_file(path):\n    h = hashlib.sha256()\n    with Path(path).open(\'rb\') as stream:\n        for block in iter(lambda: stream.read(1024*1024), b\'\'):h.update(block)\n    return h.hexdigest()\n\n\ndef canonical(value):\n    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(\',\', \':\')).encode()).hexdigest()\n\n\ndef atomic_json(path, value):\n    path = Path(path);path.parent.mkdir(parents=True, exist_ok=True)\n    temporary = path.with_suffix(path.suffix+\'.tmp\')\n    temporary.write_text(json.dumps(value, indent=2, allow_nan=False)+\'\\n\', encoding=\'utf-8\');temporary.replace(path)\n\n\ndef atomic_csv(path, frame):\n    path = Path(path);path.parent.mkdir(parents=True, exist_ok=True)\n    temporary = path.with_suffix(path.suffix+\'.tmp\');frame.to_csv(temporary, index=False);temporary.replace(path)\n\n\ndef freeze(path, value):\n    if Path(path).is_file():require(json.loads(Path(path).read_text()) == value, \'Frozen E8 inputs/configuration changed: \'+str(path))\n    else:atomic_json(path, value)\n\n\ndef truth(values):\n    text = values.astype(str).str.lower()\n    require(text.isin([\'true\', \'false\', \'1\', \'0\', \'1.0\', \'0.0\']).all(), \'Invalid Boolean value\')\n    return text.isin([\'true\', \'1\', \'1.0\'])\n\n\ndef baseline_beta(frame, languages):\n    means = frame.groupby([\'source\', \'tag\'], sort=True).lm.mean().reset_index()\n    require(len(means) == 40, \'Baseline must retain original40 directions\')\n    source = np.array([languages.index(v) for v in means.source])\n    target = np.array([languages.index(v) for v in means.tag])\n    n = len(languages)\n    x = np.column_stack([np.ones(40)]+[(source == j).astype(float)-(source == n-1).astype(float) for j in range(n-1)]+\n                        [(target == j).astype(float)-(target == n-1).astype(float) for j in range(n-1)])\n    require(np.linalg.matrix_rank(x) == 21, \'Historical additive baseline unidentified\')\n    b = np.linalg.lstsq(x, means.lm.to_numpy(), rcond=None)[0]\n    return dict(zip(languages, np.r_[b[n:], -b[n:].sum()]))\n\n\ndef load_inputs(config):\n    root = Path(config[\'input\']);inventory, studies, locks, prior = [], {}, {}, {}\n    def read_json(path):\n        require(path.is_file(), \'Missing saved input: \'+str(path))\n        inventory.append({\'path\': str(path), \'sha256\': sha_file(path), \'bytes\': path.stat().st_size})\n        return json.loads(path.read_text())\n    split = read_json(root/\'frozen_meaning_split.json\')\n    require(canonical(split) == config[\'expected_split_identity\'], \'Original frozen intervention split changed\')\n    require(sha_file(root/\'sample_identity.csv\') == SAMPLE_HASH and split[\'sample_hash\'] == SAMPLE_HASH, \'Original sample identity changed\')\n    inventory.append({\'path\': str(root/\'sample_identity.csv\'), \'sha256\': SAMPLE_HASH,\n                      \'bytes\': (root/\'sample_identity.csv\').stat().st_size})\n    manifest = pd.read_csv(root/\'sample_identity.csv\', usecols=[\'pair\', \'sentence_id\', \'corpus_sentence_id\'], dtype={\'corpus_sentence_id\': str})\n    require(len(manifest) == 30000 and not manifest.duplicated([\'pair\', \'sentence_id\']).any(), \'Original750x40 manifest incomplete\')\n    meaning_identity = manifest.groupby(\'sentence_id\').corpus_sentence_id.agg(lambda x: x.iloc[0])\n    require(manifest.groupby(\'sentence_id\').corpus_sentence_id.nunique().eq(1).all(), \'Inconsistent original corpus IDs\')\n    baseline_ids, intervention_ids = split[\'baseline450\'], split[\'intervention300\']\n    require(len(set(baseline_ids)) == 450 and len(set(intervention_ids)) == 300 and\n            set(baseline_ids).isdisjoint(intervention_ids), \'450/300 split changed\')\n    for study, role in STUDIES.items():\n        folder = root/role\n        lock = read_json(folder/\'run_lock.json\');locks[study] = lock\n        require(canonical(lock) == config[\'expected_locks\'][study], \'Historical collector lock changed: \'+study)\n        require(lock[\'split_hash\'] == SAMPLE_HASH and lock[\'generation_meanings\'] in [100, 150], \'Historical split/generation rule changed\')\n        targets, sources, control = lock[\'targets\'], lock[\'sources\'], lock[\'control\']\n        require(len(targets) == 6 and len(sources) == 4 and set(targets).isdisjoint(sources), \'Crossed language design changed\')\n        require(control not in targets+sources and control == \'urd_Arab\', \'Control tag changed\')\n        if study == \'nllb\':\n            require(all(lock[k] == locks[\'it2\'][k] for k in [\'sources\', \'targets\', \'control\', \'generation_ids_sha256\']), \'Cross-model cells/generation subset differ\')\n        baseline = read_json(folder/\'analysis/baseline_analysis.json\')\n        prior[study] = read_json(folder/\'analysis/intervention_analysis.json\')\n        for name, data in [(\'baseline_analysis.json\', baseline), (\'intervention_analysis.json\', prior[study])]:\n            require(canonical(data) == config[\'expected_analyses\'][study][name], \'Historical analysis changed: \'+study+\'/\'+name)\n        diagonal = read_json(folder/\'analysis/diagonal_reproduction.json\')\n        require(diagonal[\'full_max_delta\'] <= diagonal[\'tolerance\'], \'Historical diagonal reproduction failed\')\n        components = COMPONENTS[study]\n        required = [\'sentence_id\', \'corpus_sentence_id\', \'source\', \'tag\', \'text\', \'eligible\', \'reason\', \'lm\', \'nll\', \'closure_maxerr\']+components\n        def read_tf(path, ids, source, tag, text):\n            require(path.is_file(), \'Missing recorded TF cell; no inferred replacement or model rerun: \'+str(path))\n            digest = sha_file(path);frame = pd.read_csv(path, dtype={\'corpus_sentence_id\': str}, usecols=lambda c: c in required)\n            require(set(required) <= set(frame), \'Saved TF schema differs: \'+str(path))\n            require(len(frame) == len(ids) and not frame.sentence_id.duplicated().any() and set(frame.sentence_id) == set(ids), \'Missing/duplicate recorded meaning in \'+str(path))\n            require(frame.source.eq(source).all() and frame.tag.eq(tag).all() and frame.text.eq(text).all(), \'Cell labels do not match file name\')\n            require(frame.corpus_sentence_id.eq(frame.sentence_id.map(meaning_identity)).all(), \'TF corpus meaning identity changed\')\n            okay = truth(frame.eligible);numeric = frame.loc[okay, components+[\'lm\', \'nll\', \'closure_maxerr\']]\n            require(np.isfinite(numeric).all().all(), \'Nonfinite eligible saved TF statistic\')\n            require(np.allclose(numeric[components].sum(1), 1, atol=1e-5, rtol=0) and\n                    numeric.closure_maxerr.le(1e-5).all(), \'Historical component closure failed\')\n            require(np.allclose(numeric.lm, numeric.lexical, atol=1e-7, rtol=0), \'LM/lexical convention changed\')\n            require(numeric[components].ge(-1e-6).all().all() and numeric[components].le(1+1e-6).all().all(), \'Component outside attention-share range\')\n            frame[\'eligible\'] = okay\n            inventory.append({\'path\': str(path), \'sha256\': digest, \'bytes\': path.stat().st_size,\n                              \'study\': study, \'rows\': len(frame), \'eligible_rows\': int(okay.sum())})\n            return frame\n        baseline_frames = []\n        for i, pair in enumerate(sorted(manifest.pair.unique()), 1):\n            source, target = pair.split(\'__\')\n            frame = read_tf(folder/\'baseline_tf\'/(pair+\'__\'+target+\'.csv\'), baseline_ids, source, target, target)\n            require(frame.eligible.all(), \'Historical baseline450 has missing/undefined rows; do not silently change frozen beta\')\n            baseline_frames.append(frame)\n            if i == 1 or i % 10 == 0:progress(f\'{study}: verified baseline CSV {i}/40\')\n        baseline_inventory = {Path(row[\'path\']).name: row[\'sha256\'] for row in inventory\n                              if row.get(\'study\') == study and Path(row[\'path\']).parent.name == \'baseline_tf\'}\n        require(canonical(baseline_inventory) == config[\'expected_baseline_inventory\'][study],\n                \'Historical baseline CSV hashes differ from the completed E1 audit\')\n        bf = pd.concat(baseline_frames, ignore_index=True)\n        beta = baseline_beta(bf, sorted(baseline[\'beta_hat_baseline450\']))\n        require(max(abs(beta[lang]-baseline[\'beta_hat_baseline450\'][lang]) for lang in beta) < 1e-10,\n                \'Frozen historical beta does not reproduce; do not substitute E4/E6 beta\')\n        cells = list(itertools.product(sources, targets+[control], targets));frames = []\n        for i, (source, tag, text) in enumerate(cells, 1):\n            frames.append(read_tf(folder/\'intervention_tf\'/(source+\'__\'+tag+\'__\'+text+\'.csv\'), intervention_ids, source, tag, text))\n            if i == 1 or i % 16 == 0 or i == len(cells):progress(f\'{study}: verified intervention CSV {i}/168; no tensors loaded\')\n        intervention = pd.concat(frames, ignore_index=True)\n        path = folder/\'analysis/generation_lid_chrf.csv\'\n        require(path.is_file(), \'Missing already-scored output-only generation rows\')\n        # Never copy/read hypothesis or reference text columns. No new LID/model inference.\n        generation_cols = [\'sentence_id\', \'corpus_sentence_id\', \'source\', \'tag\', \'generated_length\',\n                           \'ended_with_eos\', \'generation_hit_cap\', \'degenerate\', \'lid_label\', \'off_target\', \'chrfpp\']\n        generation = pd.read_csv(path, dtype={\'corpus_sentence_id\': str}, usecols=lambda c: c in generation_cols)\n        require(set(generation_cols) <= set(generation), \'Saved generation-score schema changed\')\n        inventory.append({\'path\': str(path), \'sha256\': sha_file(path), \'bytes\': path.stat().st_size, \'study\': study, \'rows\': len(generation)})\n        n = lock[\'generation_meanings\'];ids = split[\'generation150\'] if n == 150 else split[\'generation100\']\n        require(hashlib.sha256(\'|\'.join(map(str, ids)).encode()).hexdigest() == lock[\'generation_ids_sha256\'], \'Frozen generation ID hash differs\')\n        require(set(ids) <= set(intervention_ids) and len(generation) == n*28 and\n                not generation.duplicated([\'sentence_id\', \'source\', \'tag\']).any(), \'Generation membership/duplicates changed\')\n        expected_gen = set(itertools.product(ids, sources, targets+[control]))\n        require(set(generation[[\'sentence_id\', \'source\', \'tag\']].itertuples(index=False, name=None)) == expected_gen, \'Generation grid incomplete\')\n        require(generation.corpus_sentence_id.eq(generation.sentence_id.map(meaning_identity)).all(), \'Generation IDs changed\')\n        require(not np.isinf(generation.chrfpp).any() and generation.chrfpp.dropna().between(0, 100).all(), \'Invalid recorded chrF score\')\n        for field in [\'ended_with_eos\', \'generation_hit_cap\', \'degenerate\', \'off_target\']:generation[field] = truth(generation[field])\n        require(generation.off_target.eq(generation.lid_label != generation.tag).all(), \'Saved LID flags disagree with labels\')\n        require(prior[study][\'lid_revision\'] == \'85cd6716494360367b75f642b5bc78667605d0b4\', \'Historical LID revision changed\')\n        studies[study] = {\'intervention\': intervention, \'generation\': generation, \'beta\': beta, \'lock\': lock}\n    return studies, split, prior, pd.DataFrame(inventory)\n\n\ndef layout(sources, tags, texts, drop_flag=False):\n    grid = list(itertools.product(sources, tags, texts))\n    s = np.array([sources.index(v[0]) for v in grid]);t = np.array([tags.index(v[1]) for v in grid]);x = np.array([texts.index(v[2]) for v in grid])\n    def coding(index, n):return np.eye(n)[index, :-1]-(index == n-1)[:, None]\n    sc, tc, xc = coding(s, len(sources)), coding(t, len(tags)), coding(x, len(texts))\n    design = np.column_stack([np.ones(len(grid)), sc, tc, xc, (tc[:, :, None]*xc[:, None, :]).reshape(len(grid), -1)])\n    mask = np.array([not(drop_flag and a == \'mar_Deva\' and (b == \'hin_Deva\' or c == \'hin_Deva\')) for a, b, c in grid])\n    expected_rank = 1+len(sources)-1+len(tags)-1+len(texts)-1+(len(tags)-1)*(len(texts)-1)\n    require(np.linalg.matrix_rank(design[mask]) == expected_rank == design.shape[1], \'E8 interaction design unidentified\')\n    inverse = np.linalg.pinv(design[mask])\n    return {\'sources\': sources, \'tags\': tags, \'texts\': texts, \'grid\': grid, \'mask\': mask,\n            \'X\': design, \'inverse\': inverse, \'rank\': expected_rank, \'main_rank\': len(sources)+len(tags)+len(texts)-2}\n\n\ndef effect_labels(spec):\n    return [(\'intercept\', \'grand_mean\', \'\')]+[(\'source\', s, \'\') for s in spec[\'sources\']]+[(\'tag\', t, \'\') for t in spec[\'tags\']]+\\\n        [(\'forced_text\', x, \'\') for x in spec[\'texts\']]+[(\'tag_by_text\', t, x) for t in spec[\'tags\'] for x in spec[\'texts\']]\n\n\ndef effects(coefficient, spec):\n    # Input (..., coefficients, outcomes). Convert to physical sum-zero effects.\n    fitted = np.einsum(\'dp,...pc->...dc\', spec[\'X\'], coefficient)\n    a = fitted.reshape(*fitted.shape[:-2], len(spec[\'sources\']), len(spec[\'tags\']), len(spec[\'texts\']), fitted.shape[-1])\n    mu = a.mean(axis=(-4, -3, -2))\n    source = a.mean(axis=(-3, -2))-mu[..., None, :]\n    tag = a.mean(axis=(-4, -2))-mu[..., None, :]\n    text = a.mean(axis=(-4, -3))-mu[..., None, :]\n    gamma = a.mean(axis=-4)-mu[..., None, None, :]-tag[..., :, None, :]-text[..., None, :, :]\n    return np.concatenate([mu[..., None, :], source, tag, text, gamma.reshape(*gamma.shape[:-3], -1, gamma.shape[-1])], axis=-2)\n\n\ndef cube(frame, ids, spec, columns):\n    index = pd.MultiIndex.from_tuples([(i, *cell) for i in ids for cell in spec[\'grid\']], names=[\'sentence_id\', \'source\', \'tag\', \'text\'])\n    ordered = frame.set_index([\'sentence_id\', \'source\', \'tag\', \'text\']).reindex(index)\n    require(ordered.eligible.fillna(False).all() and np.isfinite(ordered[columns]).all().all(), \'Incomplete selected factorial cube\')\n    return ordered[columns].to_numpy(float).reshape(len(ids), len(spec[\'grid\']), len(columns))\n\n\ndef sufficient(y, nll, spec):\n    mask = spec[\'mask\'];a = y[:, mask];z = nll[:, mask]\n    coeff = np.einsum(\'pd,ndc->npc\', spec[\'inverse\'], a)\n    zcoeff = z@spec[\'inverse\'].T\n    zc = z-z.mean(1, keepdims=True);ac = a-a.mean(1, keepdims=True)\n    return {\'coefficient\': coeff, \'zcoefficient\': zcoeff, \'zz\': np.sum(zc*zc, axis=1),\n            \'zy\': np.sum(zc[:, :, None]*ac, axis=1)}\n\n\ndef estimate(stat, weights, spec):\n    weights = weights/weights.sum(1, keepdims=True)\n    b, p, c = len(weights), stat[\'coefficient\'].shape[1], stat[\'coefficient\'].shape[2]\n    coefficient = (weights@stat[\'coefficient\'].reshape(len(stat[\'coefficient\']), -1)).reshape(b, p, c)\n    zcoefficient = weights@stat[\'zcoefficient\']\n    raw = effects(coefficient, spec)\n    # Meaning fixed effects + shared factorial effects + row-level NLL, using FWL.\n    # NLL is affected by the intervention; adjustment is descriptive, not mediation.\n    x = spec[\'X\'][spec[\'mask\']]\n    zfit = zcoefficient@x.T;zfit -= zfit.mean(1, keepdims=True)\n    yfit = np.einsum(\'dp,bpc->bdc\', x, coefficient);yfit -= yfit.mean(1, keepdims=True)\n    denominator = weights@stat[\'zz\']-np.sum(zfit*zfit, axis=1)\n    numerator = weights@stat[\'zy\']-np.sum(zfit[:, :, None]*yfit, axis=1)\n    require(np.all(denominator > 1e-12), \'NLL covariate collinear; no automatic omission\')\n    nll_slope = numerator/denominator[:, None]\n    adjusted = effects(coefficient-zcoefficient[:, :, None]*nll_slope[:, None, :], spec)\n    return raw, adjusted, nll_slope\n\n\ndef paired_slopes(y, beta):\n    # Shape meanings x4 sources x6 tags x6 forced texts; orientation B,A.\n    diag = np.diagonal(y, axis1=2, axis2=3)\n    tag = y-diag[:, :, None, :]\n    text = np.swapaxes(y, 2, 3)-diag[:, :, None, :]\n    predictor = beta[:, None]-beta[None, :]\n    mask = ~np.eye(6, dtype=bool)\n    denominator = float(4*np.sum(predictor[mask]**2))\n    require(denominator > 1e-20, \'Frozen beta has no target contrast\')\n    return np.column_stack([np.sum(np.where(mask[None, None], value*predictor[None, None], 0), axis=(1, 2, 3))/denominator\n                            for value in [tag, text]])\n\n\ndef analyze_model(study, data, ids, weights, root, n_boot, prior):\n    lock = data[\'lock\'];components = COMPONENTS[study];columns = components+[\'nll\']\n    sources, targets = lock[\'sources\'], lock[\'targets\'];tags = targets+[lock[\'control\']]\n    spec = layout(sources, tags, targets)\n    y = cube(data[\'intervention\'], ids, spec, columns)\n    stat = sufficient(y[:, :, :-1], y[:, :, -1], spec)\n    point, adjusted, nll_slope = estimate(stat, np.ones((1, len(ids))), spec)\n    labels = effect_labels(spec);point, adjusted = point[0], adjusted[0]\n    raw_draws = np.empty((n_boot, len(labels), len(components)))\n    adjusted_draws = np.empty_like(raw_draws);nll_draws = np.empty((n_boot, len(components)))\n    for begin in range(0, n_boot, 512):\n        end = min(n_boot, begin+512)\n        raw_draws[begin:end], adjusted_draws[begin:end], nll_draws[begin:end] = estimate(stat, weights[begin:end], spec)\n        progress(f\'{study}: joint meaning-cluster bootstrap {end:,}/{n_boot:,}; raw and NLL-adjusted factorial effects\')\n    require(np.allclose(point[0].sum(), 1, atol=1e-5) and np.allclose(point[1:].sum(-1), 0, atol=1e-5), \'Factorial component-effect closure failed\')\n    require(np.allclose(adjusted[1:].sum(-1), 0, atol=1e-5) and abs(nll_slope.sum()) < 1e-5, \'Adjusted component-effect closure failed\')\n    rows = []\n    for label, values, draws in [(\'unadjusted\', point, raw_draws), (\'NLL_adjusted_descriptive\', adjusted, adjusted_draws)]:\n        low, high = np.quantile(draws, [.025, .975], axis=0)\n        for j, (term, level, other) in enumerate(labels):\n            for c, component in enumerate(components):\n                rows.append({\'study\': study, \'adjustment\': label, \'component\': component, \'term\': term,\n                    \'level\': level, \'forced_text_level\': other, \'estimate\': values[j, c], \'ci_low\': low[j, c], \'ci_high\': high[j, c],\n                    \'meaning_clusters\': len(ids), \'interval\': \'nominal95 meaning-bootstrap; exploratory except LM simultaneous interaction intervals\'})\n    atomic_csv(root/\'factorial_effects.csv\', pd.DataFrame(rows))\n    low, high = np.quantile(nll_draws, [.025, .975], axis=0)\n    atomic_csv(root/\'NLL_covariate_slopes.csv\', pd.DataFrame([{\'study\': study, \'component\': c, \'estimate\': nll_slope[0, j],\n        \'ci_low\': low[j], \'ci_high\': high[j], \'scope\': \'row-level NLL with meaning and factorial fixed effects; descriptive\'} for j, c in enumerate(components)]))\n    start = next(i for i, label in enumerate(labels) if label[0] == \'tag_by_text\')\n    lm = components.index(\'lexical\');interaction = point[start:, lm]\n    gamma_draws = raw_draws[:, start:, lm];noise = gamma_draws-interaction\n    point_rms = float(np.sqrt(np.mean(interaction**2)));noise_rms = np.sqrt(np.mean(noise**2, axis=1))\n    p = float((1+np.sum(noise_rms >= point_rms))/(n_boot+1))\n    per_meaning = effects(stat[\'coefficient\'], spec)[:, start:, lm]\n    noise_energy = float(np.var(per_meaning, axis=0, ddof=1).mean()/len(ids))\n    global_result = {\'study\': study, \'outcome\': \'lexical\', \'grid\': \'4sources x7tags x6texts\', \'meaning_clusters\': len(ids),\n        \'main_effect_rank\': spec[\'main_rank\'], \'interaction_model_rank\': spec[\'rank\'], \'interaction_df\': 30,\n        \'interaction_RMS\': point_rms, \'estimated_sampling_noise_RMS\': float(np.sqrt(noise_energy)),\n        \'noise_debiased_interaction_energy\': point_rms**2-noise_energy,\n        \'centered_meaning_bootstrap_p\': p, \'Bonferroni_p_two_models\': min(1., 2*p),\n        \'null_draws_ge_observed\': int(np.sum(noise_rms >= point_rms)), \'bootstrap_draws\': n_boot,\n        \'null\': \'recenter whole-meaning interaction vectors at zero; approximate cluster sampling-noise test, not an exact randomization test\'}\n    atomic_json(root/\'global_interaction_test.json\', global_result)\n    temporary = root/\'primary_bootstrap.tmp.npz\'\n    np.savez_compressed(temporary, interaction=interaction, interaction_draws=gamma_draws, null_RMS=noise_rms,\n                        per_meaning_interactions=per_meaning,\n                        interaction_levels=np.array([t+\'__\'+x for _, t, x in labels[start:]]))\n    temporary.replace(root/\'primary_bootstrap.npz\')\n    # Paired contrasts relative to the tag=text diagonal, including the control tag.\n    cells = y[:, :, :-1].reshape(len(ids), 4, 7, 6, len(components))\n    diagonal = cells[:, :, np.arange(6), np.arange(6), :]\n    delta = cells-diagonal[:, :, None, :, :]\n    require(np.allclose(delta.sum(-1), 0, atol=1e-5), \'Paired component-change closure failed\')\n    flat = delta.reshape(len(ids), -1)\n    draws = weights@flat/len(ids);lo, hi = np.quantile(draws, [.025, .975], axis=0)\n    observed = delta.mean(0).reshape(-1);lo = lo.reshape(4, 7, 6, -1);hi = hi.reshape(4, 7, 6, -1)\n    means = cells.mean(0);observed = observed.reshape(4, 7, 6, -1)\n    cell_rows = []\n    for s, source in enumerate(sources):\n        for t, tag in enumerate(tags):\n            for x, text in enumerate(targets):\n                for c, component in enumerate(components):\n                    cell_rows.append({\'study\': study, \'source\': source, \'requested_tag\': tag, \'forced_text\': text,\n                        \'matched\': tag == text, \'control_tag\': tag == lock[\'control\'],\n                        \'flagged_mar_hin\': source == \'mar_Deva\' and (tag == \'hin_Deva\' or text == \'hin_Deva\'),\n                        \'tag_location\': ARCHITECTURE[study], \'component\': component, \'mean_mass\': means[s, t, x, c],\n                        \'paired_delta_vs_same_text_own_tag\': observed[s, t, x, c], \'delta_ci_low\': lo[s, t, x, c], \'delta_ci_high\': hi[s, t, x, c],\n                        \'meaning_clusters\': len(ids), \'interval\': \'nominal95; exploratory cell-level contrast\'})\n    atomic_csv(root/\'paired_cell_components.csv\', pd.DataFrame(cell_rows))\n    old_slopes = paired_slopes(cells[:, :, :6, :, lm], np.array([data[\'beta\'][t] for t in targets]))\n    for j, term in enumerate([\'tag\', \'text\']):\n        if len(ids) == 300:require(abs(old_slopes[:, j].mean()-prior[\'b_\'+term]) < 1e-8, \'Earlier paired \'+term+\' slope does not reproduce\')\n    boot_slopes = weights@old_slopes/len(ids)\n    lo, hi = np.quantile(boot_slopes, [.025, .975], axis=0)\n    atomic_csv(root/\'original_paired_slopes_check.csv\', pd.DataFrame([{\'study\': study, \'contrast\': term,\n        \'estimate\': old_slopes[:, j].mean(), \'ci_low\': lo[j], \'ci_high\': hi[j], \'original_reported\': prior[\'b_\'+term],\n        \'interpretation\': \'projection onto frozen beta differences; not a causal mediation share\'} for j, term in enumerate([\'tag\', \'text\'])]))\n    within_mask = ~np.eye(6, dtype=bool)\n    control_per_meaning = np.abs(delta[:, :, 6, :, lm]).mean(axis=(1, 2))\n    within_per_meaning = np.abs(delta[:, :, :6, :, lm][:, :, within_mask]).mean(axis=(1, 2))\n    contrast = control_per_meaning-within_per_meaning\n    lo, hi = np.quantile(weights@contrast/len(ids), [.025, .975])\n    atomic_json(root/\'control_tag_check.json\', {\'study\': study, \'control_mean_absolute_LM_shift\': float(control_per_meaning.mean()),\n        \'within_set_mean_absolute_LM_shift\': float(within_per_meaning.mean()), \'control_minus_within\': float(contrast.mean()),\n        \'ci_low\': float(lo), \'ci_high\': float(hi), \'interpretation\': \'negative supports smaller control shift; descriptive fixed-language meaning-bootstrap contrast\'})\n    return global_result, (interaction, gamma_draws, per_meaning), spec, y\n\n\ndef sensitivity(study, data, ids, spec, y, output):\n    targets, sources = spec[\'texts\'], spec[\'sources\'];rows = []\n    alternatives = [(\'full_grid\', sources, spec[\'tags\'], targets, False),\n                    (\'within_six_targets\', sources, targets, targets, False),\n                    (\'drop_flagged_mar_hin_cells\', sources, spec[\'tags\'], targets, True)]\n    alternatives += [(\'leave_target_\'+t, sources, [x for x in spec[\'tags\'] if x != t], [x for x in targets if x != t], False) for t in targets]\n    alternatives += [(\'leave_source_\'+s, [x for x in sources if x != s], spec[\'tags\'], targets, False) for s in sources]\n    for name, selected_sources, tags, texts, drop_flag in alternatives:\n        sub = layout(selected_sources, tags, texts, drop_flag)\n        values = cube(data[\'intervention\'], ids, sub, [\'lm\', \'nll\'])\n        stat = sufficient(values[:, :, :1], values[:, :, 1], sub)\n        raw, adjusted, _ = estimate(stat, np.ones((1, len(ids))), sub)\n        labels = effect_labels(sub)\n        for adjustment, coefficients in [(\'unadjusted\', raw[0, :, 0]), (\'NLL_adjusted_descriptive\', adjusted[0, :, 0])]:\n            gamma = coefficients[np.array([t[0] == \'tag_by_text\' for t in labels])]\n            tag = {a: coefficients[j] for j, (term, a, _) in enumerate(labels) if term == \'tag\'}\n            text = {a: coefficients[j] for j, (term, a, _) in enumerate(labels) if term == \'forced_text\'}\n            common = [t for t in texts if t in data[\'beta\']]\n            beta = np.array([data[\'beta\'][t] for t in common]);beta -= beta.mean()\n            def association(values):\n                effect = np.array([values[t] for t in common]);effect -= effect.mean()\n                return float(effect@beta/(beta@beta)), float(spearmanr(effect, beta).statistic)\n            ts, tr = association(tag);xs, xr = association(text)\n            rows.append({\'study\': study, \'scope\': name, \'adjustment\': adjustment, \'cells_used\': int(sub[\'mask\'].sum()),\n                \'design_rank\': sub[\'rank\'], \'interaction_RMS\': float(np.sqrt(np.mean(gamma*gamma))),\n                \'tag_slope_on_beta\': ts, \'text_slope_on_beta\': xs, \'tag_spearman_beta\': tr, \'text_spearman_beta\': xr,\n                \'interpretation\': \'point stability on observed selected languages/sources; no language-population interval or mediation share\'})\n    # Main-model mean-cell fit is descriptive; never label it held-out prediction.\n    b = np.einsum(\'pd,dc->pc\', spec[\'inverse\'], y.mean(0)[spec[\'mask\'], :-1])\n    pred = spec[\'X\']@b;observed = y.mean(0)[:, :-1]\n    lm = COMPONENTS[study].index(\'lexical\');total = float(np.sum((observed[:, lm]-observed[:, lm].mean())**2))\n    error = float(np.sum((observed[:, lm]-pred[:, lm])**2))\n    atomic_csv(output/\'sensitivity_points.csv\', pd.DataFrame(rows))\n    atomic_json(output/\'descriptive_cell_fit.json\', {\'interaction_model_mean_cell_R2\': 1-error/total,\n        \'scope\': \'in-sample168 cell description; not generalization\', \'parameters\': spec[\'rank\']})\n\n\ndef generation_summary(study, data, weights, split, output):\n    generation = data[\'generation\'];n = data[\'lock\'][\'generation_meanings\']\n    ids = split[\'generation150\'] if n == 150 else split[\'generation100\']\n    # Different, explicitly frozen150-meaning support; paired across source/tag conditions.\n    rng = np.random.default_rng(20261123);counts = rng.multinomial(n, np.full(n, 1/n), size=len(weights))/n\n    rows = []\n    for (source, tag), group in generation.groupby([\'source\', \'tag\'], sort=True):\n        group = group.set_index(\'sentence_id\').loc[ids]\n        for metric in [\'off_target\', \'chrfpp\', \'generation_hit_cap\', \'degenerate\']:\n            values = group[metric].to_numpy(float);finite = np.isfinite(values)\n            denominator = counts@finite.astype(float)\n            draws = np.divide(counts@np.where(finite, values, 0.), denominator,\n                out=np.full(len(counts), np.nan), where=denominator > 0)\n            lo, hi = np.nanquantile(draws, [.025, .975]) if finite.any() else (np.nan, np.nan)\n            rows.append({\'study\': study, \'source\': source, \'requested_tag\': tag, \'metric\': metric,\n                \'estimate\': float(values[finite].mean()) if finite.any() else np.nan, \'ci_low\': lo, \'ci_high\': hi, \'meanings\': n,\n                \'recorded_finite_scores\': int(finite.sum()), \'recorded_missing_scores\': int((~finite).sum()),\n                \'count\': int(values.sum()) if metric != \'chrfpp\' else np.nan,\n                \'flagged_mar_hin\': source == \'mar_Deva\' and tag == \'hin_Deva\',\n                \'support\': \'all original output-only generations; no forced-text dimension\',\n                \'interval\': \'nominal95 paired meaning bootstrap; all-zero event intervals are degenerate, not zero population risk\'})\n    atomic_csv(output/\'generation_manipulation_check.csv\', pd.DataFrame(rows))\n    # Original cap flag can miss forced-EOS termination exactly at max_length.\n    flags = generation.assign(reaches_length_256=generation.generated_length.ge(256))\n    atomic_csv(output/\'generation_length_flags.csv\', flags[[\'sentence_id\', \'source\', \'tag\', \'generated_length\',\n               \'ended_with_eos\', \'generation_hit_cap\', \'reaches_length_256\', \'degenerate\', \'off_target\', \'chrfpp\']])\n    return {\'study\': study, \'generation_meanings\': n, \'outputs\': len(generation),\n        \'off_target_count\': int(generation.off_target.sum()),\n        \'mean_chrfpp\': float(generation.chrfpp.mean()) if generation.chrfpp.notna().any() else None,\n        \'missing_saved_chrfpp\': int(generation.chrfpp.isna().sum()),\n        \'recorded_no_EOS_cap_hits\': int(generation.generation_hit_cap.sum()),\n        \'length_at_least_256\': int(flags.reaches_length_256.sum()), \'degenerate_count\': int(generation.degenerate.sum()),\n        \'no_generated_attention_available\': True, \'references\': \'requested-tag-language reference, not forced-text language\'}\n\n\ndef complete_support(studies, original_ids):\n    common = set(original_ids);missing = []\n    for study, data in studies.items():\n        frame = data[\'intervention\'];valid = frame.groupby(\'sentence_id\').eligible.all()\n        common &= set(valid[valid].index)\n        for row in frame[~frame.eligible].itertuples(index=False):\n            missing.append({\'study\': study, \'sentence_id\': row.sentence_id, \'source\': row.source, \'tag\': row.tag,\n                            \'text\': row.text, \'reason\': str(row.reason) if pd.notna(row.reason) else \'recorded ineligible TF row; no reason supplied\'})\n    ids = [i for i in original_ids if i in common]\n    require(len(ids) >= 200, \'Fewer than200 common complete intervention meanings; inspect support rather than weakening rules\')\n    return ids, missing\n\n\ndef run(config):\n    output = Path(config[\'output\']);output.mkdir(parents=True, exist_ok=True)\n    require(sha_file(Path(__file__)) == config[\'source_sha256\'], \'E8 source changed\')\n    studies, split, prior, inventory = load_inputs(config)\n    ids, missing = complete_support(studies, split[\'intervention300\'])\n    lock = {\'configuration\': config, \'input_inventory\': inventory.fillna(\'\').to_dict(\'records\'), \'common_intervention_meanings\': ids,\n            \'packages\': {p: importlib.metadata.version(p) for p in [\'numpy\', \'pandas\', \'scipy\', \'matplotlib\']}}\n    freeze(output/\'analysis_lock.json\', lock)\n    fingerprint = canonical(lock)\n    atomic_csv(output/\'input_inventory.csv\', inventory)\n    atomic_csv(output/\'recorded_ineligible_rows.csv\', pd.DataFrame(missing, columns=[\'study\', \'sentence_id\', \'source\', \'tag\', \'text\', \'reason\']))\n    atomic_json(output/\'meaning_support.json\', {\'original_intervention\': split[\'intervention300\'], \'common_complete\': ids,\n        \'excluded_jointly\': sorted(set(split[\'intervention300\'])-set(ids)), \'no_resplit\': True, \'baseline_coefficients\': \'original historical fp32 baseline450, not E4/E6 beta\'})\n    progress(f\'E8: {len(ids)}/300 common meanings; full4x7x6 grid, both historical fp32 models\')\n    rng = np.random.default_rng(config[\'seed\']);weights = rng.multinomial(len(ids), np.full(len(ids), 1/len(ids)), size=config[\'n_boot\'])\n    np.savez_compressed(output/\'meaning_bootstrap_weights.npz\', counts=weights.astype(np.uint16), meanings=np.array(ids), seed=config[\'seed\'])\n    results, gamma, designs, behavior = [], {}, [], []\n    for study, data in studies.items():\n        root = output/study;root.mkdir(parents=True, exist_ok=True)\n        complete = root/\'complete.json\'\n        if complete.is_file():\n            saved = json.loads(complete.read_text())\n            require(saved[\'fingerprint\'] == fingerprint, \'E8 model checkpoint identity changed\')\n            for name, digest in saved[\'files\'].items():require(sha_file(root/name) == digest, \'E8 cached result changed: \'+study+\'/\'+name)\n            result = json.loads((root/\'global_interaction_test.json\').read_text())\n            with np.load(root/\'primary_bootstrap.npz\', allow_pickle=False) as z:\n                values = z[\'interaction\'], z[\'interaction_draws\'], z[\'per_meaning_interactions\']\n            spec = layout(data[\'lock\'][\'sources\'], data[\'lock\'][\'targets\']+[data[\'lock\'][\'control\']], data[\'lock\'][\'targets\'])\n            generation_result = json.loads((root/\'generation_summary.json\').read_text())\n            progress(study+\': verified completed E8 model checkpoint; skipping its bootstrap and analysis\')\n        else:\n            result, values, spec, y = analyze_model(study, data, ids, weights, root, config[\'n_boot\'], prior[study])\n            sensitivity(study, data, ids, spec, y, root)\n            generation_result = generation_summary(study, data, weights, split, root)\n            atomic_json(root/\'generation_summary.json\', generation_result)\n            files = {p.name: sha_file(p) for p in sorted(root.iterdir()) if p.is_file() and p.name != \'complete.json\' and \'.tmp\' not in p.name}\n            atomic_json(complete, {\'fingerprint\': fingerprint, \'files\': files})\n        results.append(result);gamma[study] = values\n        behavior.append(generation_result)\n        designs.append({\'study\': study, \'tag_location\': ARCHITECTURE[study], \'sources\': spec[\'sources\'],\n            \'requested_tags\': spec[\'tags\'], \'forced_texts\': spec[\'texts\'], \'main_rank\': spec[\'main_rank\'], \'interaction_rank\': spec[\'rank\'],\n            \'attention_components\': COMPONENTS[study], \'punctuation_definition\': \'historical coarse token category; not E4 Unicode-P-only\',\n            \'preprocessing\': \'historical collector; process-start hash seed and input-token IDs were not frozen as in E4 v3\'})\n    # One simultaneous LM interaction-cell interval family across both models, all84 cells.\n    standardized = []\n    for study, (point, draws, per_meaning) in gamma.items():\n        se = per_meaning.std(0, ddof=1)/np.sqrt(len(ids))\n        standardized.append(np.divide(np.abs(draws-point), se, out=np.zeros_like(draws), where=se > 1e-15))\n    critical = float(np.quantile(np.column_stack(standardized).max(1), .95));rows = []\n    for study, (point, draws, per_meaning) in gamma.items():\n        se = per_meaning.std(0, ddof=1)/np.sqrt(len(ids));tags = studies[study][\'lock\'][\'targets\']+[studies[study][\'lock\'][\'control\']]\n        texts = studies[study][\'lock\'][\'targets\']\n        for j, (tag, text) in enumerate(itertools.product(tags, texts)):\n            rows.append({\'study\': study, \'requested_tag\': tag, \'forced_text\': text, \'interaction\': point[j],\n                \'simultaneous_low\': point[j]-critical*se[j], \'simultaneous_high\': point[j]+critical*se[j],\n                \'critical_max_standardized_deviation\': critical, \'family\': \'all84 lexical interaction cells, both models\',\n                \'scope\': \'approximate95 simultaneous whole-meaning bootstrap; fixed selected languages/sources\'})\n    simultaneous = pd.DataFrame(rows)\n    atomic_csv(output/\'E8_simultaneous_lexical_interactions.csv\', simultaneous)\n    atomic_csv(output/\'E8_global_interaction_tests.csv\', pd.DataFrame(results))\n    atomic_csv(output/\'E8_generation_summary.csv\', pd.DataFrame(behavior))\n    atomic_json(output/\'E8_design_and_provenance.json\', designs)\n    reports = []\n    for study in STUDIES:\n        cells = pd.read_csv(output/study/\'paired_cell_components.csv\')\n        index = [\'study\', \'source\', \'requested_tag\', \'forced_text\', \'matched\', \'control_tag\', \'flagged_mar_hin\', \'tag_location\']\n        report = cells.pivot(index=index, columns=\'component\', values=\'paired_delta_vs_same_text_own_tag\').reset_index()\n        report = report.rename(columns={c: c+\'_delta\' for c in COMPONENTS[study]})\n        quality = pd.read_csv(output/study/\'generation_manipulation_check.csv\').pivot(\n            index=[\'study\', \'source\', \'requested_tag\'], columns=\'metric\', values=\'estimate\').reset_index()\n        report = report.merge(quality, on=[\'study\', \'source\', \'requested_tag\'], validate=\'many_to_one\')\n        report[\'output_language_correct_fraction\'] = 1-report.off_target\n        report[\'FG_quality_support\'] = \'same source/tag output-only generations; reused across text columns, not independent TF-cell outputs\'\n        reports.append(report)\n    atomic_csv(output/\'E8_cell_report.csv\', pd.concat(reports, ignore_index=True))\n    import matplotlib\n    matplotlib.use(\'Agg\')\n    import matplotlib.pyplot as plt\n    fig, axes = plt.subplots(1, 2, figsize=(12, 5), constrained_layout=True)\n    scale = max(abs(simultaneous.interaction).max(), 1e-8)\n    for ax, study in zip(axes, STUDIES):\n        lock = studies[study][\'lock\'];tags = lock[\'targets\']+[lock[\'control\']];texts = lock[\'targets\']\n        values = simultaneous[simultaneous.study == study].interaction.to_numpy().reshape(7, 6)\n        im = ax.imshow(values, cmap=\'RdBu_r\', vmin=-scale, vmax=scale)\n        ax.set_xticks(range(6), texts, rotation=45, ha=\'right\');ax.set_yticks(range(7), tags)\n        ax.set_xlabel(\'Forced reference-text language\');ax.set_ylabel(\'Requested tag language\');ax.set_title(study.upper()+\' lexical tag × text interaction\')\n    fig.colorbar(im, ax=axes, label=\'Mean LM deviation from additive tag + text effects\')\n    for suffix in [\'png\', \'pdf\']:fig.savefig(output/(\'E8_tag_text_interactions.\'+suffix), dpi=200)\n    plt.close(fig)\n    atomic_json(output/\'status.json\', {\'E8_CPU_extension_complete\': True, \'new_GPU_runs\': 0, \'common_intervention_meanings\': len(ids),\n        \'bootstrap_repetitions\': config[\'n_boot\'], \'models\': list(STUDIES), \'historical_inputs_modified\': False,\n        \'limits\': \'retrospective historical collectors; fixed high-contrast languages; off-distribution TF; coarse punctuation; NLL is post-intervention; no mediation claim\'})\n    print(\'\\nGlobal LM interaction tests:\\n\'+pd.DataFrame(results).to_string(index=False), flush=True)\n    print(\'\\nOriginal output-only generation manipulation checks:\\n\'+pd.DataFrame(behavior).to_string(index=False), flush=True)\n    print(\'E8 saved. Report every pre-set contrast and provenance limitation; a small p-value is not evidence of causal mediation.\', flush=True)\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser();parser.add_argument(\'--config\', required=True)\n    run(json.loads(Path(parser.parse_args().config).read_text()))\n')


