with zipfile.ZipFile(temporary,'w',compression=zipfile.ZIP_DEFLATED) as bundle:
    for path in paths+[OUTPUT_ROOT/'completed_all.json']:bundle.write(path,str(path.relative_to(OUTPUT_ROOT)))
temporary.replace(archive)
print(json.dumps(status,indent=2));print('Results:',OUTPUT_ROOT);print('Archive:',archive)
